/**
 * Scenario and attempt types.
 *
 * A scenario is plain data: a resident's baseline, ordered events grouped into nodes, decision points with explicit
 * choices and points, and branch conditions. The engine (engine.ts) interprets it deterministically. Nothing here is
 * generated by a model, and nothing here is a clinical measurement: indices are illustrative, 100 = the resident's usual.
 */

export type Dimension = 'mobility' | 'intake' | 'engagement' | 'orientation' | 'fluids' | 'sleep'
export type EventKind = 'observation' | 'documentation' | 'action' | 'unknown'
export type Tag = 'observed' | 'assumption' | 'unknown'
export type Criterion = 'recognition' | 'communication' | 'evidence' | 'handover'
export type Phase = 'prebrief' | 'playing' | 'decision' | 'handover' | 'complete'

export interface SimTime {
  day: number
  clock: string
}

/** Someone (or the chart) who can know about the change. Rows of the timeline and of "who knew". */
export interface Person {
  id: string
  label: string
  role: string
}

/** A hand-off of information about the change. `passed: false` is a hand-off that should have carried it and didn't. */
export interface Flow {
  from: string
  to: string
  passed: boolean
  note: string
}

export interface ScenarioEvent {
  id: string
  day: number
  clock: string
  kind: EventKind
  /** Who saw, wrote or did it. */
  source: string
  /** The person (row) this event belongs to. */
  by: string
  /** People who learn of the change by seeing it themselves. */
  aware?: string[]
  /** Hand-offs of information this event represents. */
  flows?: Flow[]
  /** What the timeline shows. */
  text: string
  /** The resident's own words, if any. */
  quote?: string
  /** Short neutral phrasing used as a handover fact. */
  fact: string
  /** Illustrative index per dimension, 100 = this resident's usual. Never a clinical measure. */
  measures?: Partial<Record<Dimension, number>>
  /** Only shown if an earlier decision chose one of these choices. */
  when?: { choices: string[] }
}

export interface DimensionDef {
  key: Dimension
  label: string
  /** What usual looks like for this resident, in words. */
  usual: string
}

export interface Resident {
  id: string
  name: string
  preferredName: string
  pronoun: 'she' | 'he' | 'they'
  age: number
  room: string
  wing: string
  summary: string
  about: string[]
  baseline: { id: string; dimension: Dimension; text: string }[]
}

export interface Statement {
  id: string
  text: string
  answer: Tag
  why: string
}

export type Next = string | Record<string, string>

export interface Choice {
  id: string
  label: string
  detail: string
  /** Points toward appropriate communication/action, out of the decision's communicationMax. */
  communication: number
  /** True when the choice presents an assumption (a guessed cause, a conclusion) as if it were a finding. */
  assumes?: boolean
  /** Why the points were earned or lost, judged only on what was known when the choice was made. */
  feedback: string
  next: Next
}

export type Recognition =
  | {
      kind: 'dimensions'
      prompt: string
      options: { id: string; label: string; changed: boolean; why: string }[]
      pointsPerHit: number
      penaltyPerFalse: number
      max: number
    }
  | {
      kind: 'trend'
      prompt: string
      options: { id: string; label: string; points: number; why: string }[]
      max: number
    }

export interface DecisionPoint {
  id: string
  at: SimTime
  title: string
  prompt: string
  recognition: Recognition
  statements: Statement[]
  pointsPerStatement: number
  choices: Choice[]
  communicationMax: number
  /** The reasoning a thoughtful staff member would show here. */
  expected: string
}

export interface HandoverSpec {
  to: string
  purpose: string
  situation: { text: string; factIds: string[] }
  recommendation: string
  expected: string
}

export interface ScenarioNode {
  id: string
  label: string
  /** Learning stage, for the progress bar. */
  stage: 'B' | 'C'
  events: ScenarioEvent[]
  decision?: DecisionPoint
  next?: Next
  handover?: HandoverSpec
}

export interface Course {
  id: string
  label: string
  summary: string
}

export interface Scenario {
  id: string
  version: number
  title: string
  subtitle: string
  blurb: string
  role: string
  days: string[]
  /** The stretch of time the scenario covers, for time axes. Fixed, so the axis never hints at what comes next. */
  window: { start: SimTime; end: SimTime }
  people: Person[]
  resident: Resident
  dimensions: DimensionDef[]
  /** The usual week before the simulation, for the chart. Illustrative. */
  baselineSeries: { label: string; values: Partial<Record<Dimension, number>> }[]
  courses: Course[]
  defaultCourse: string
  start: string
  nodes: Record<string, ScenarioNode>
  insight: string
}

// ── Attempt state ────────────────────────────────────────────────────────────

export interface DecisionInput {
  /** Recognition answer: changed dimension ids, or a single trend id. */
  recognition: string[]
  tags: Record<string, Tag>
  choice: string
}

export interface ScoreLine {
  criterion: Criterion
  item: string
  earned: number
  max: number
  reason: string
}

export interface DecisionRecord {
  decisionId: string
  nodeId: string
  at: SimTime
  input: DecisionInput
  /** Event ids revealed when the decision was made: the only evidence it is judged on. */
  evidence: string[]
  lines: ScoreLine[]
}

export interface DraftSection {
  text: string
  factIds: string[]
}

export interface HandoverDraft {
  situation: DraftSection
  background: DraftSection
  assessment: DraftSection
  recommendation: DraftSection
  unknowns: DraftSection[]
}

export type DraftSource = 'gemini' | 'template'

export interface HandoverRecord {
  draft: HandoverDraft
  /** Where the draft the player started from came from; the submitted text is always the player's. */
  startedFrom: DraftSource | 'blank'
  lines: ScoreLine[]
}

export interface AttemptState {
  scenarioId: string
  version: number
  course: string
  phase: Phase
  nodeId: string
  /** Events revealed in the current node. */
  cursor: number
  revealed: string[]
  path: string[]
  decisions: DecisionRecord[]
  handover?: HandoverRecord
}

export interface Fact {
  id: string
  kind: 'baseline' | EventKind
  when: string | null
  source: string
  text: string
}
